head.script:

scwin.onpageload = function() {
	var jsonData = [{col1:"a1",col2:"b1"},{col1:"a2",col2:"b1"},{col1:"a3",col2:"b1"},{col1:"a4",col2:"b1"},{col1:"a5",col2:"b1"}
					,{col1:"a6",col2:"b1"},{col1:"a7",col2:"b1"},{col1:"a8",col2:"b1"},{col1:"a9",col2:"b1"}
					,{col1:"a10",col2:"b10"},{col1:"a11",col2:"b1"},{col1:"a12",col2:"b1"},{col1:"a13",col2:"b1"}
					,{col1:"a14",col2:"b1"},{col1:"a15",col2:"b1"},{col1:"a16",col2:"b1"},{col1:"a17",col2:"b1"}];
	dataList1.setJSON(jsonData);

};

scwin.onpageunload = function() {

};


scwin.trigger1_onclick = function(e) {
	//
};


scwin.simulateWrapper = function(target, type, options) {
	WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
	scwin.simulateWrapper('#gridView1_customFilter_list_items_main', 'key-combo', {
		combo: 'down-arrow'
	});
}

scwin.checkVal = function() {
	return document.getElementsByClassName('w2list_listColumn')[6].checked == false;
}
scwin.unitTest = function() {
	//init
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_column8_filter').click()");
	WebSquare.wUnit.addCommand("pause", "400");
	WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
	WebSquare.wUnit.addCommand("pause", "400");
	WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
	WebSquare.wUnit.addCommand("pause", "400");
	WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
	WebSquare.wUnit.addCommand("pause", "400");	
	WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
	WebSquare.wUnit.addCommand("pause", "400");
	WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
	WebSquare.wUnit.addCommand("pause", "400");	
	WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2list_listColumn')[7].click()");
	WebSquare.wUnit.addCommand("pause", "400");	
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "400");
	//Run  and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}
scwin.unitTest()
